package com.zajel.app;

import android.app.*;import android.graphics.Color;import android.os.Bundle;import android.widget.*;import com.zajel.app.core.AppContainer;import com.zajel.app.domain.*;import java.util.*;
public final class CommunitiesActivity extends Activity{LinearLayout root;AppContainer c;TextView status;public void onCreate(Bundle b){super.onCreate(b);c=((ZajelApplication)getApplication()).container();root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(32,48,32,24);root.setBackgroundColor(Color.WHITE);setContentView(root);TextView h=new TextView(this);h.setText("Communities");h.setTextSize(28);root.addView(h);Button create=new Button(this);create.setText("Create community");root.addView(create);create.setOnClickListener(v->{EditText e=new EditText(this);e.setHint("Community name");new AlertDialog.Builder(this).setView(e).setPositiveButton("Create",(d,w)->c.communities.create(e.getText().toString(),"",new com.zajel.app.data.CommunityRepository.Callback<Community>(){public void success(Community x){load();}public void error(Exception z){}})).show();});status=new TextView(this);root.addView(status);load();}void load(){c.communities.myCommunities(new com.zajel.app.data.CommunityRepository.Callback<List<Community>>(){public void success(List<Community>x){runOnUiThread(()->{status.setText(x.isEmpty()?"No communities":"Your communities");for(Community n:x){TextView t=new TextView(CommunitiesActivity.this);t.setText(n.title+"\n"+n.description);t.setTextSize(18);t.setPadding(0,16,0,16);root.addView(t);}});}public void error(Exception e){runOnUiThread(()->status.setText("Unable to load communities"));}});}}
